-- Generated by the full-seed builder; part of the bigger presentation data set.

-- More cards and sealed product: newer sets of every game, prices from the market at the time of
-- writing. Pictures: the official scan, other printings (Japanese, parallel / alternate art) and two
-- views drawn from the scan at seed time (seed/gen/...). Every downloaded key is in image-sources.txt.


-- Union Arena now covers more series.
UPDATE game_attribute ga
   SET options = '["Jujutsu Kaisen", "Demon Slayer", "One Punch Man", "Attack on Titan", "Solo Leveling", "Chainsaw Man"]'::jsonb
  FROM game g
 WHERE g.id = ga.game_id AND g.code = 'UNION_ARENA' AND ga.attr_key = 'series';


