              description, attributes, days_ago)
  JOIN game g ON g.code = v.game
  JOIN catalog_category c ON c.code = v.category AND (c.game_id IS NULL OR c.game_id = g.id)
  LEFT JOIN card_set s ON s.game_id = g.id AND s.code = v.set_code;


